R_trig1(CLK := g_bAxisMoveDoneCheckM);
IF R_trig1.Q THEN
  g_bAxisMoveDoneCheckM := FALSE;
  nAxisDoneState := 1;
END_IF;
CASE nAxisDoneState OF
  0:
   nAxisDoneState := 0;
