	(*1:z轴运动到位  2-4:通用轴1-3运动到位  5-10:支撑轴1-6运动到位 11-13:下料轴运动到位  14-15:除尘轴1-2 16:中卡移动避让轴 17:下料轴4运动到位*)
	IF g_dM320PValue=1.0 THEN
	  IF g_bZAxisMoveDoneM320 THEN
		M.ENABLE[320] := 0;
		g_bExecuteFinishedM320 := FALSE;
        g_bFinishedM320_1 := FALSE;
        nAxisDoneState := 0;
	  END_IF;  
	ELSIF g_dM320PValue=2.0 THEN
	  IF g_bUniversalAxis1MoveDoneM320 THEN
		M.ENABLE[320] := 0;
